 public async ValueTask<(bool Succeeded,int?Number,string?Error)>CreateAsync(int type,DateOnly from,DateOnly to,string comments,string user,CancellationToken t){await using var c=await Open(t);await using var cmd=Cmd("SP_CreaPlanilla",c);cmd.CommandType=CommandType.StoredProcedure;cmd.Parameters.Add("@TipoPlanilla",SqlDbType.Int).Value=type;cmd.Parameters.Add("@FechaIni",SqlDbType.Date).Value=from.ToDateTime(TimeOnly.MinValue);cmd.Parameters.Add("@FechaFin",SqlDbType.Date).Value=to.ToDateTime(TimeOnly.MinValue);P(cmd,"@Comentario",500,comments);P(cmd,"@UsuarioCrea",100,user);var code=cmd.Parameters.Add("@pCodError",SqlDbType.Int);code.Direction=ParameterDirection.Output;var message=cmd.Parameters.Add("@pMensajeError",SqlDbType.VarChar,300);message.Direction=ParameterDirection.Output;await cmd.ExecuteNonQueryAsync(t);var ok=Convert.ToInt32(code.Value)==0;int? number=null;if(ok){await using var q=Cmd("SELECT MAX([Consecutivo]) FROM [dbo].[Planilla] WHERE [UsuarioCrea]=@User",c);P(q,"@User",100,user);var v=await q.ExecuteScalarAsync(t);if(v is not DBNull&&v is not null)number=Convert.ToInt32(v);}return(ok,number,ok?null:Convert.ToString(message.Value));}
